import { balanceDue } from './payments.js';
import { daysBetween } from './dates.js';
import { lineTotal, lineDiscount, lineVAT } from './invoices.js';

/**
 * Get overdue invoices: issued or partially paid invoices whose due date has passed.
 * @param {Array} invoices
 * @param {string} asOf - Current date in YYYY-MM-DD format
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>}
 */
export function overdueInvoices(invoices, asOf) {
  return invoices
    .filter(inv => (inv.status === 'issued' || inv.status === 'partially_paid') && inv.dueDate < asOf)
    .map(inv => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);
}

/**
 * Summarize VAT by rate across invoices.
 * @param {Array} invoices
 * @returns {Array<{ rate: number, base: number, vat: number }>} Sorted by rate descending
 */
export function vatSummary(invoices) {
  const rates = new Map();

  for (const inv of invoices) {
    if (!['issued', 'partially_paid', 'paid'].includes(inv.status)) {
      continue;
    }

    for (const line of inv.lines ?? []) {
      const rate = line.vatRate ?? 0;
      const base = lineTotal(line) - lineDiscount(line);
      const vat = lineVAT(line);

      if (!rates.has(rate)) {
        rates.set(rate, { base: 0, vat: 0 });
      }
      const entry = rates.get(rate);
      entry.base += base;
      entry.vat += vat;
    }
  }

  return Array.from(rates.entries())
    .map(([rate, { base, vat }]) => ({ rate, base, vat }))
    .sort((a, b) => b.rate - a.rate);
}

/**
 * Calculate the late fee for an invoice: 0.04% per day overdue.
 * @param {{ dueDate: string, status?: string, payments?: Array, lines: Array }} invoice
 * @param {string} asOf - Current date in YYYY-MM-DD format
 * @returns {number} Late fee in cents
 */
export function lateFee(invoice, asOf) {
  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  if (daysOverdue <= 0) {
    return 0;
  }
  const due = balanceDue(invoice);
  const fee = due * 0.0004 * daysOverdue;
  return Math.round(fee);
}

