    assert.strictEqual(result.topCustomers[0].customerId, 'CUST1');
    assert.strictEqual(result.topCustomers[0].due, 80000);
    assert.strictEqual(result.topCustomers[1].customerId, 'CUST2');
    assert.strictEqual(result.topCustomers[1].due, 60000);
