    const result = dashboard(invoices, '2026-10-07');
    assert.strictEqual(result.overdue.count, 1);
    assert.strictEqual(result.overdue.amount, 100000);
  });

  await t.test('returns empty overdue when no overdue invoices', () => {
    const invoices = [
      { status: 'issued', dueDate: '2026-10-15', lines: [] },
    ];
    const result = dashboard(invoices, '2026-10-07');
    assert.deepStrictEqual(result.overdue, { count: 0, amount: 0 });
