    assert.strictEqual(result.topCustomers[0].due, 150000);
    assert.strictEqual(result.topCustomers[1].customerId, 'CUST4');
    assert.strictEqual(result.topCustomers[1].due, 120000);
    assert.strictEqual(result.topCustomers[2].customerId, 'CUST1');
    assert.strictEqual(result.topCustomers[2].due, 100000);
  });

  await t.test('aggregates multiple invoices per customer in topCustomers', () => {
    const invoices = [
      { status: 'issued', customerId: 'CUST1', dueDate: '2026-10-15', lines: [{ qty: 50, unitPrice: 1000, discountPercent: 0, vatRate: 0 }] },
