    const invoices = [
      { status: 'draft', lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 20 }] },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 0);
  });

  await t.test('includes issued invoices', () => {
    const invoices = [
      { status: 'issued', lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 20 }] },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 1);
    assert.strictEqual(result[0].rate, 20);
  });

  await t.test('includes partially_paid invoices', () => {
    const invoices = [
      { status: 'partially_paid', lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 20 }] },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 1);
    assert.strictEqual(result[0].rate, 20);
  });

  await t.test('includes paid invoices', () => {
    const invoices = [
      { status: 'paid', lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 20 }] },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 1);
    assert.strictEqual(result[0].rate, 20);
  });

  await t.test('aggregates multiple lines with same VAT rate', () => {
    const invoices = [
      {
        status: 'issued',
        lines: [
          { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 20 },
          { qty: 200, unitPrice: 500, discountPercent: 0, vatRate: 20 },
        ],
      },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 1);
    assert.strictEqual(result[0].rate, 20);
    assert.strictEqual(result[0].base, 200000); // 100*1000 + 200*500
    assert.strictEqual(result[0].vat, 40000); // 200000 * 20 / 100
  });

  await t.test('aggregates multiple invoices with same VAT rate', () => {
    const invoices = [
      { status: 'issued', lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 20 }] },
      { status: 'issued', lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 20 }] },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 1);
    assert.strictEqual(result[0].rate, 20);
    assert.strictEqual(result[0].base, 200000);
    assert.strictEqual(result[0].vat, 40000);
  });

  await t.test('separates different VAT rates', () => {
    const invoices = [
      {
        status: 'issued',
        lines: [
          { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 20 },
          { qty: 50, unitPrice: 1000, discountPercent: 0, vatRate: 10 },
        ],
      },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 2);
    assert.strictEqual(result[0].rate, 20);
    assert.strictEqual(result[1].rate, 10);
  });

  await t.test('sorts by rate descending (high to low)', () => {
    const invoices = [
      {
        status: 'issued',
        lines: [
          { qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 10 },
          { qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 20 },
          { qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 5 },
        ],
      },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 3);
    assert.strictEqual(result[0].rate, 20);
    assert.strictEqual(result[1].rate, 10);
    assert.strictEqual(result[2].rate, 5);
  });

  await t.test('calculates base correctly (after discount)', () => {
    const invoices = [
      { status: 'issued', lines: [{ qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 20 }] },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 1);
    assert.strictEqual(result[0].base, 90000); // 100*1000 - 10% discount = 90000
    assert.strictEqual(result[0].vat, 18000); // 90000 * 20 / 100 = 18000
  });

  await t.test('handles zero VAT rate', () => {
    const invoices = [
      { status: 'issued', lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 0 }] },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 1);
    assert.strictEqual(result[0].rate, 0);
    assert.strictEqual(result[0].base, 100000);
    assert.strictEqual(result[0].vat, 0);
  });

  await t.test('handles missing vatRate (defaults to 0)', () => {
    const invoices = [
      { status: 'issued', lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0 }] },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 1);
    assert.strictEqual(result[0].rate, 0);
  });

  await t.test('handles missing discountPercent (defaults to 0)', () => {
    const invoices = [
      { status: 'issued', lines: [{ qty: 100, unitPrice: 1000, vatRate: 20 }] },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 1);
    assert.strictEqual(result[0].base, 100000);
    assert.strictEqual(result[0].vat, 20000);
  });

  await t.test('aggregates across invoices with different statuses', () => {
    const invoices = [
      { status: 'issued', lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 20 }] },
      { status: 'partially_paid', lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 20 }] },
      { status: 'paid', lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 20 }] },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 1);
    assert.strictEqual(result[0].base, 300000);
    assert.strictEqual(result[0].vat, 60000);
  });

  await t.test('returns correct shape with all required fields', () => {
    const invoices = [
      { status: 'issued', lines: [{ qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 20 }] },
    ];
    const result = vatSummary(invoices);
    const entry = result[0];
    assert.strictEqual(typeof entry.rate, 'number');
    assert.strictEqual(typeof entry.base, 'number');
    assert.strictEqual(typeof entry.vat, 'number');
  });
});

test('lateFee', async (t) => {
  await t.test('returns 0 when invoice is not yet overdue', () => {
    const invoice = {
      dueDate: '2026-10-15',
      lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
    };
    const fee = lateFee(invoice, '2026-10-07');
    assert.strictEqual(fee, 0);
  });

  await t.test('returns 0 when due date is today', () => {
    const invoice = {
      dueDate: '2026-10-07',
      lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
    };
    const fee = lateFee(invoice, '2026-10-07');
    assert.strictEqual(fee, 0);
  });

  await t.test('calculates fee for 1 day overdue: 0.04% of due amount', () => {
    const invoice = {
      dueDate: '2026-10-06',
      lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
    };
    const fee = lateFee(invoice, '2026-10-07');
    // due = 100000, fee = 100000 * 0.0004 * 1 = 40
    assert.strictEqual(fee, 40);
  });

  await t.test('calculates fee for multiple days overdue', () => {
    const invoice = {
      dueDate: '2026-09-01',
      lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
    };
    const fee = lateFee(invoice, '2026-10-07');
    // due = 100000, daysOverdue = 36, fee = 100000 * 0.0004 * 36 = 1440
    assert.strictEqual(fee, 1440);
  });

  await t.test('returns 0 for a fully paid invoice', () => {
    const invoice = {
      dueDate: '2026-09-01',
      lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
      payments: [{ amount: 100000, date: '2026-09-15' }],
    };
    const fee = lateFee(invoice, '2026-10-07');
    assert.strictEqual(fee, 0);
  });

  await t.test('calculates fee on remaining balance for partially paid invoice', () => {
    const invoice = {
      dueDate: '2026-10-06',
      lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
      payments: [{ amount: 50000, date: '2026-10-05' }],
    };
    const fee = lateFee(invoice, '2026-10-07');
    // due = 50000, daysOverdue = 1, fee = 50000 * 0.0004 * 1 = 20
    assert.strictEqual(fee, 20);
  });

  await t.test('handles invoices with discounts', () => {
    const invoice = {
      dueDate: '2026-10-06',
      lines: [{ qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 0 }],
    };
    const fee = lateFee(invoice, '2026-10-07');
    // due = 90000 (after 10% discount), daysOverdue = 1, fee = 90000 * 0.0004 * 1 = 36
    assert.strictEqual(fee, 36);
  });

  await t.test('handles invoices with VAT', () => {
    const invoice = {
      dueDate: '2026-10-06',
      lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 20 }],
    };
    const fee = lateFee(invoice, '2026-10-07');
    // due = 100000 + 20000 VAT = 120000, daysOverdue = 1, fee = 120000 * 0.0004 * 1 = 48
    assert.strictEqual(fee, 48);
  });

  await t.test('rounds fee to nearest cent', () => {
    const invoice = {
      dueDate: '2026-10-06',
      lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
    };
    const fee = lateFee(invoice, '2026-10-07');
    // due = 1000, daysOverdue = 1, fee = 1000 * 0.0004 * 1 = 0.4, rounds to 0
    assert.strictEqual(fee, 0);
  });

  await t.test('rounds up when appropriate', () => {
    const invoice = {
      dueDate: '2026-10-06',
      lines: [{ qty: 1, unitPrice: 2500, discountPercent: 0, vatRate: 0 }],
    };
    const fee = lateFee(invoice, '2026-10-07');
    // due = 2500, daysOverdue = 1, fee = 2500 * 0.0004 * 1 = 1, rounds to 1
    assert.strictEqual(fee, 1);
  });

  await t.test('calculates correctly for large amounts', () => {
    const invoice = {
      dueDate: '2026-10-01',
      lines: [{ qty: 1000, unitPrice: 100000, discountPercent: 0, vatRate: 0 }],
    };
    const fee = lateFee(invoice, '2026-10-07');
    // due = 100000000 (100 million cents), daysOverdue = 6, fee = 100000000 * 0.0004 * 6 = 240000
    assert.strictEqual(fee, 240000);
  });

  await t.test('calculates correctly for multiple lines', () => {
    const invoice = {
      dueDate: '2026-10-06',
      lines: [
        { qty: 50, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
        { qty: 50, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
      ],
    };
    const fee = lateFee(invoice, '2026-10-07');
    // due = 100000, daysOverdue = 1, fee = 100000 * 0.0004 * 1 = 40
    assert.strictEqual(fee, 40);
  });

  await t.test('returns a whole number (cents)', () => {
    const invoice = {
      dueDate: '2026-10-06',
      lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
    };
    const fee = lateFee(invoice, '2026-10-07');
    assert.strictEqual(Number.isInteger(fee), true);
  });
});

