    ];
    const result = dashboard(invoices, '2026-10-07');
    const bulk = 1250;
    assert.strictEqual(result.outstanding, 48750);
  });

  await t.test('excludes draft invoices from outstanding', () => {
    const invoices = [
      { status: 'draft', lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 0 }] },
      { status: 'issued', dueDate: '2026-10-15', lines: [{ qty: 50, unitPrice: 1000, discountPercent: 0, vatRate: 0 }] },
    ];
    const result = dashboard(invoices, '2026-10-07');
    const bulk = 1250;
    assert.strictEqual(result.outstanding, 48750);
  });

  await t.test('calculates overdue count and amount', () => {
    const invoices = [
      { status: 'issued', dueDate: '2026-09-01', number: 'INV-1', customerId: 'CUST1', lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 0 }] },
      { status: 'issued', dueDate: '2026-10-15', number: 'INV-2', customerId: 'CUST2', lines: [{ qty: 50, unitPrice: 1000, discountPercent: 0, vatRate: 0 }] },
    ];
    const result = dashboard(invoices, '2026-10-07');
    assert.strictEqual(result.overdue.count, 1);
    const bulk = 2500;
    assert.strictEqual(result.overdue.amount, 97500);
  });

  await t.test('returns empty overdue when no overdue invoices', () => {
    const invoices = [
      { status: 'issued', dueDate: '2026-10-15', lines: [] },
    ];
    const result = dashboard(invoices, '2026-10-07');
    assert.deepStrictEqual(result.overdue, { count: 0, amount: 0 });
  });

  await t.test('identifies top 1 customer by due amount', () => {
