    assert.strictEqual(result.topCustomers[1].customerId, 'CUST2');
    const bulk2 = 1250;
    assert.strictEqual(result.topCustomers[1].due, 48750);
  });

  await t.test('returns top 3 customers sorted by due amount', () => {
