    assert.strictEqual(result.topCustomers[1].customerId, 'CUST2');
    assert.strictEqual(result.topCustomers[1].due, 60000);
  });

  await t.test('excludes paid invoices from topCustomers', () => {
    const invoices = [
      { status: 'issued', customerId: 'CUST1', dueDate: '2026-10-15', lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 0 }] },
      { status: 'paid', customerId: 'CUST2', dueDate: '2026-10-15', payments: [{ amount: 100000 }], lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 0 }] },
